export const GAP_PACK_PRO_SOURCE_COMMIT = 'eabcbd6ef56c10f5e79b489cf5b477890833c52d';

const GAP_PACK_PRO_TEXT: Record<string, string> = {
  "gap-pack2-01": "IPv4 Protocol=17 (IANA Assigned Internet Protocol Numbers) направляет IP payload в UDP, а Protocol=6 — в TCP. Демультиплексирование L3→L4 происходит до обработки полей source/destination port. TCP/443 и UDP/443 принадлежат разным пространствам сокетов.\n\nДля UDP endpoint выбирается по локальному адресу/порту, а при connected socket также по remote tuple; для TCP — по соединению и его 4-tuple. Номер 443 не задаёт тип транспорта и не позволяет угадать формат заголовка.",
  "gap-pack2-02": "При PMTU=1500 длина заголовка IPv4 равна 24 байтам (IHL=6), длина заголовка TCP — 32 байтам (Data Offset=8). Оба поля длины измеряются 32-битными словами; IPv4 Total Length включает заголовок IP, транспорт и данные.\n\nМаксимум данных в данном сегменте: min(MSS получателя, PMTU − длина IP-заголовка − длина TCP-заголовка) = min(1460, 1500−24−32) = 1444 байта. MSS ограничивает данные TCP, а не весь IP-пакет; расчёт использует фактические опции (RFC 9293, RFC 6691).",
  "gap-pack2-03": "IPv4 payload length=3020−20=3000. При MTU 1500 максимальная non-final fragment data length равна floor((1500−20)/8)×8=1480. RFC 791 задаёт Fragment Offset в единицах 8 octets от начала исходного IP payload.\n\nДиапазоны: [0,1479], [1480,2959], [2960,2999], offset=0/185/370, MF=1/1/0. У фрагментов заново формируются IP header/Total Length/checksum; последний MF=0 указывает конец исходной датаграммы, а не завершённость получения.",
  "gap-pack2-04": "IPv6 forwarding path не допускает фрагментацию транзитным маршрутизатором (RFC 8200). При outgoing link MTU 1400 и размере IPv6 packet 1560 узел выполняет discard и посылает ICMPv6 Type 2 Packet Too Big с MTU=1400 (RFC 4443).\n\nОтправитель применяет Path MTU Discovery (RFC 8201) и при необходимости формирует меньшие пакеты или собственный Fragment header. Ни извещение о 1560, ни forwarding превышающего MTU пакета не допустимы в заданной модели.",
  "gap-pack2-05": "Ethernet FCS вычисляется для передаваемого на данном hop MAC frame, а IPv4 Header Checksum в RFC 791 покрывает исключительно IPv4 header. Изменение IP payload без изменения IP header не затрагивает вторую проверку; пересчитанная FCS корректна относительно уже модифицированного кадра.\n\nEnd-to-end integrity нельзя выводить из hop-local CRC. UDP/TCP checksum, application digest или криптографическая аутентификация охватывают разные границы; их результат в условии ещё не проверен.",
  "gap-pack2-06": "GRE создаёт outer IPv4 header с destination=198.51.100.2 и encapsulated inner IPv4 destination=10.80.0.20 (RFC 2784). Transit FIB lookup без decapsulation выполняется по outer destination, поэтому выбирается /32 via P.\n\nInner dst используется на tunnel endpoint после decapsulation. Source addresses R/S не являются lookup destination при обычной destination-based forwarding, отсутствие PBR указано контекстом задачи.",
  "gap-pack2-07": "RFC 3021 разрешает IPv4 /31 на point-to-point links: два значения host bit используются как адреса интерфейсов, без обычного выделения subnet/network и directed broadcast. У 192.0.2.8/31 допустимы ровно .8 и .9.\n\nСледующий /31 начинается с .10, поэтому любые пары с .10/.11 выходят за пределы выделенного блока. Правило действительно при поддержке /31 обоими peer и именно для point-to-point интерфейса.",
  "gap-pack2-08": "В 46 байтах Ethernet payload находится IPv4-пакет с Total Length=40; остальные 6 байт — padding. Заголовок IPv4 занимает 20 байт (IHL=5), поэтому IP payload равен 20 байтам. UDP Length=20 включает восьмибайтовый заголовок UDP, и пользовательские данные занимают 12 байт.\n\nДекапсуляция ограничивает каждую вложенную единицу её собственным полем длины (RFC 894, RFC 768). Ethernet padding не входит в IPv4 Total Length и не выдаётся приложению как часть UDP-датаграммы.",
  "gap-pack2-09": "У IPv4 Fragment Offset=185 payload начинается на смещении 185×8=1480 bytes относительно IP payload исходной датаграммы. Только fragment offset=0 содержит начальный UDP header с source/destination ports.\n\nКлюч reassembly context включает src/dst IPv4, Protocol=17 и Identification (RFC 791). Для stateful classification необходимы reassembly или связывание non-initial fragments с первым; эвристики «последняя пара IP» и вычисление портов из offset невалидны.",
  "gap-pack2-10": "При PPP Link/Network phase и согласованном IPCP IPv4-пакет передаётся с PPP Protocol=0x0021 (RFC 1661, RFC 1332). Адресация соседнего hop предоставлена point-to-point моделью PPP: ARP/MAC resolution здесь не требуется.\n\nIPv4 header Protocol=17 обозначает UDP payload внутри IP и не совпадает с PPP Protocol. IPCP — negotiation control plane, а не действие per packet; дополнительное peer discovery после установления PPP не нужно.",
  "gap-pack2-11": "Для указанного авторитетного ответа на QTYPE=AAAA сочетание RCODE=NOERROR, пустой Answer и SOA в Authority при исключённом referral означает NODATA (RFC 2308). Отсутствует RRset запрошенного типа; существование имени дополнительно подтверждено действительным A RRset.\n\nNXDOMAIN относится к отсутствию имени, а не отдельного RRset. TC=0 не даёт основания для TCP fallback из-за усечения; пустая Answer не заменяет полученный RCODE значением SERVFAIL.",
  "gap-pack2-12": "В DHCPv4 с relay ненулевой giaddr=192.0.2.1 является основанием для выбора address pool по клиентскому link, согласно RFC 2131. Отсюда выбран 192.0.2.0/24, при отсутствии дополнительных server policies.\n\nIP source relay=203.0.113.1 определяет transport reachability, Option 50 — requested IP, ciaddr=0 — отсутствие настроенного текущего адреса; ни одно из них не заменяет giaddr для subnet selection.",
  "gap-pack2-13": "HTTP 206 с Content-Range: bytes 2000-2999/6000 сообщает inclusive byte range [2000,2999] длиной 1000, а complete representation length=6000 (RFC 9110). Validated resource version позволяет merge по смещению 2000.\n\nПосле записи диапазона [0,2999] остаётся [3000,5999]. Ни Content-Length тела, ни позиция конца диапазона не означают завершённость representation; запись с offset 0 или 3000 нарушает layout файла.",
  "gap-pack2-14": "При mutual TLS цепочка client certificate валидируется сервером относительно его client-auth trust anchors. Alert unknown_ca на стороне сервера означает отсутствие доверенной CA chain для предъявленного клиента (RFC 8446).\n\nСервер должен включить C в client-auth trust store с учётом политики проверки. Server-auth trust store клиента и сертификат сервера относятся к другому направлению проверки и не разрешают unknown_ca при client authentication.",
  "gap-pack2-15": "SSH local forwarding (-L 127.0.0.1:15432:db.internal:5432) принимает локальную TCP-сессию на рабочем ПК и передаёт direct-tcpip channel через транспортное SSH-соединение (RFC 4254). SSH server на jump выполняет connect к db.internal:5432.\n\nDNS resolution целевой hostname и доступность target TCP endpoint оцениваются с jump. SSH server port и target port независимы; база не подключается обратно к 127.0.0.1 клиента.",
  "gap-pack2-16": "NTP KoD packet имеет Stratum=0 и Kiss Code RATE в Reference ID (RFC 5905). Такой ответ — control signal rate limiting, а не eligible time sample для offset/delay calculation.\n\nPoll exponent/interval требуется увеличить согласно политике клиента; уменьшение интервала только усиливает rate-limiting. Stratum=0 в KoD не означает эталонный stratum с повышенным приоритетом.",
  "gap-pack2-17": "RFC 5424 определяет PRI = facility × 8 + severity; 165 div 8 = 20, 165 mod 8 = 5. Facility=20, Severity=5 (Notice), так что criterion facility==20 выполняется, severity≤4 — нет.\n\nSeverity — порядок от 0 (Emergency) до 7 (Debug). Нельзя сравнивать фильтр с целым PRI либо округлять остаток к 4; результат — отсутствие записи в указанный специальный архив.",
  "gap-pack2-18": "Message submission через explicit TLS использует TCP/587 (RFC 6409, RFC 3207): SMTP greeting → EHLO → STARTTLS → TLS handshake → повторный EHLO → authentication по политике. Соединение начинает plaintext SMTP command phase.\n\nTCP/465 использует implicit TLS (RFC 8314): TLS ClientHello до SMTP greeting. Корректный защищённый 465 session не удовлетворяет конкретному требованию отправки STARTTLS после EHLO на 587.",
  "gap-pack2-19": "MX preference сортируют по возрастанию: 10 предпочтительнее 20 (RFC 5321). После connection failure к mx-a.example.test сервер продолжает delivery attempt к следующему MX mx-b.example.test, whose A=192.0.2.20.\n\nПри наличии MX-записей fallback на A самого example.test не заменяет очередь MX. Выбор .20 обоснован отказом более предпочтительного узла, а не тем, что число 20 означает высший приоритет.",
  "gap-pack2-20": "DHCPv4 lease timers T1=1800, T2=3150, expiry=3600 (RFC 2131). В elapsed=3200 клиент уже находится в REBINDING, но адрес остаётся валидным до 3600 при отсутствии ACK/NAK.\n\nREBINDING DHCPREQUEST передаётся broadcast с ciaddr=current leased IP, Server Identifier не включают. Unicast к прежнему серверу — RENEWING; ciaddr=0 и Server Identifier характерны для других состояний.",
  "gap-pack2-21": "TCP advertises rwnd=0, при этом outstanding data уже ACKed. Sender должен остановить normal new-data transmission; TCP persist/zero-window probes предотвращают deadlock при lost window update (RFC 9293).\n\nPersist probe solicits fresh ACK/window advertisement и не равнозначен retransmission ранее подтверждённого payload. MSS reduction или повторный SYN handshake не обходят flow-control limit.",
  "gap-pack2-22": "TCP Window Scale shift=3 обозначает multiplier 2^3=8 (RFC 7323). Field Window в SYN или SYN-ACK не масштабируется, хотя опция WS в них согласуется. Поэтому initial SYN-ACK advertised window=3000 bytes.\n\nУ последующего ACK без SYN advertised effective rwnd=3000<<3=24000 bytes. Scaling negotiated separately per direction; нельзя применять множитель к самому SYN-ACK или использовать обратное деление.",
  "gap-pack2-23": "Karn/Partridge algorithm запрещает RTT sampling по retransmitted segment без механизма, устраняющего ACK ambiguity (RFC 6298). ACK at t=700 может относиться к initial tx t=0 (700ms) или retransmission t=500 (200ms).\n\nSampleRTT для этого ACK не вычисляют и SRTT не обновляют по неоднозначному sample. RTO backoff при retransmission — отдельное состояние и не следует путать с изменением сглаженного RTT.",
  "gap-pack2-24": "TCP receiver уже committed байты [1000,1499] в in-order stream и ожидает RCV.NXT=1500. Повторный segment с Seq=1000 и Len=500 целиком duplicate, поэтому application receive queue не увеличивается.\n\nCumulative ACK остаётся 1500: потеря предыдущего ACK на сети не откатывает receiver-side RCV.NXT. ACK=2000 ложно подтвердил бы не принятый диапазон, ACK=1000 игнорировал бы ранее полученный.",
  "gap-pack2-25": "Linux datagram socket recvfrom(..., len=100, flags=0) читает один UDP message; при payload length=300 он возвращает первые 100 bytes, а tail в 200 bytes отбрасывается при truncation (recvmsg MSG_TRUNC позволяет диагностировать).\n\nОчередной recvfrom с len=512 возвращает следующую queued datagram payload=40. Datagram-oriented API не предоставляет остаток первого сообщения как продолжение stream read; UDP не переотправляет усечённое содержимое.",
  "gap-pack2-26": "FIN занимает один номер последовательности TCP (RFC 9293). Принятый по порядку FIN,ACK с Seq=5000 без payload продвигает RCV.NXT стороны B до 5001; B подтверждает ACK=5001.\n\nПосле выдачи всех данных до FIN приложение B получает EOF направления A→B. Направление B→A остаётся доступным для отправки до собственного FIN стороны B. ACK=5000 не подтверждает FIN, а запрет обратной передачи смешивает half-close со сбросом или завершением обоих направлений.",
  "gap-pack2-27": "UDP header Length=8 octets включает только обязательные source/destination ports, length и checksum; user data length=0 (RFC 768). Linux recvfrom на datagram socket успешно возвращает 0 и может заполнить source address.\n\nЭто валидный zero-length UDP payload, а не stream EOF; TCP recv==0 имеет другую семантику. Увеличение receive buffer ничего не добавит, а ожидание transport header через recvfrom неверно.",
  "gap-pack2-28": "TCP использует независимые sequence spaces по направлениям (RFC 9293). B.SND.NXT=9000 задаёт Seq первого байта B→A, а B.RCV.NXT=1500 отражается в ACK для A→B.\n\nСегмент длиной 200 имеет Seq=9000, ACK=1500; после отправки B.SND.NXT=9200, но поле Seq уже отправленного segment не меняется. ACK не зависит от количества новых B→A bytes.",
  "gap-pack2-29": "TCP flow можно нормализовать по unordered pair endpoint (192.0.2.10,51000) и (198.51.100.20,443) при protocol TCP; обратный packet имеет перевёрнутый directional 4-tuple, но тот же canonical flow key.\n\nДля полного подсчёта отдельных sessions нужна временная граница SYN/FIN/RST и проверка reuse того же tuple. При заданном вопросе о группировке встречных направлений результат один двунаправленный flow, а не два по числу directional records.",
  "gap-pack2-30": "Required in-flight TCP payload для sustained throughput определяется bandwidth-delay product: BDP=20e6 bits/s × 0.050s = 1e6 bits =125000 bytes. Congestion/receive windows должны допускать необходимый FlightSize.\n\nЭто нижняя оценка для стационарного соединения без loss и protocol overhead. TCP ACK clocking, advertised window и congestion control в реальном канале могут ограничивать throughput ниже рассчитанного значения.",
  "gap-pack3-01": "IPv4 reassembly interval coverage: fragment offset=0,len=800 охватывает [0,799], offset=200,len=400 охватывает [1600,1999]. Offset units =8 octets; MF=0 сообщает terminal offset 2000, но не гарантирует complete coverage.\n\nВ reassembly queue отсутствует [800,1599]; нельзя pass payload L4 до закрытия всех holes. RFC 791 reassembly timeout приводит к discard incomplete datagram, а не zero-fill gap.",
  "gap-pack3-02": "При re-fragmentation IPv4 исходный fragment offset=100 (800-byte origin). Outgoing MTU=620, header=20, usable data=600=75×8. Новые offsets относительно original IP payload: 100 и 100+75=175.\n\nПоскольку входной fragment имел MF=1, ни одна его новая часть не является концом original datagram, обе MF=1. Локальный конец повторного разбиения не равен глобальному final fragment (RFC 791).",
  "gap-pack3-03": "IPv6 base header fixed 40 bytes (RFC 8200), Next Header=0 указывает Hop-by-Hop Options. Для extension header Hdr Ext Len=1 означает (1+1)×8=16 bytes including первые 8 байт, а его Next Header=17 указывает UDP.\n\nСмещение UDP header от первого байта IPv6 packet: 40+16=56. IPv6 extension chain требует пошагового parsing; нельзя трактовать Next Header=0 как UDP или прибавлять Ethernet framing к IP-relative offsets.",
  "gap-pack3-04": "GRE-over-IPv4 без options расходует 20-byte outer IPv4 header и 4-byte basic GRE header (RFC 2784). Tunnel inner L3 MTU=underlay MTU−encapsulation overhead=1500−24=1476 bytes.\n\nВнутренний IPv4 header входит в 1476; отдельное вычитание 20 относится к inner payload, а не inner IP datagram MTU. При дополнительных GRE fields/IP options формула должна учитывать фактический overhead.",
  "gap-pack3-05": "VXLAN VNI — 24-bit identifier virtual network segment (RFC 7348). VTEP после UDP/VXLAN decapsulation использует VNI для выбора overlay L2 bridging domain; MAC learning/lookup выполняется с VNI scope.\n\nOuter UDP dst port (обычно 4789) обозначает сервис VXLAN, outer IP — VTEP endpoint. Повторяющиеся inner MAC и IP у разных tenant допустимы именно потому, что namespace partitioned by VNI.",
  "gap-pack3-06": "IPv4 IHL хранит число 32-bit words (RFC 791): 8×4=32 octets. IPv4 Total Length=28 включает header и payload; constraint Total Length≥IHL×4 здесь нарушен.\n\nIP parser должен reject malformed datagram, даже если L2 frame содержит больше octets (например padding). Автоматическая коррекция IHL или extension IP Length за счёт Ethernet bytes не входит в валидный IP parsing.",
  "gap-pack3-07": "SNAT меняет IPv4 Source Address. IPv4 Header Checksum охватывает изменённый 32-bit адрес, а UDP pseudo-header checksum также включает source/destination IPv4, protocol и UDP length (RFC 768).\n\nНенулевая исходная UDP checksum требует перерасчёта или корректной incremental adjustment вместе с IPv4 header checksum; неизменные UDP payload и ports не означают неизменность pseudo-header.",
  "gap-pack3-08": "RFC 8200 требует mandatory UDP checksum для обычного UDP-over-IPv6; UDP Checksum=0 невалиден вне специально оговорённых tunnel exception (RFC 6935/6936). Поэтому receiver discards packet despite valid UDP length.\n\nEthernet FCS — per-link frame CRC и не заменяет IPv6 UDP pseudo-header + payload checksum. Receiver-side generation нового check value не подтверждает то, что передал peer.",
  "gap-pack3-09": "IPv4 Header Checksum — 16-bit one's-complement checksum (RFC 791). После end-around-carry folding сумма 0xB861 инвертируется: (~0xB861)&0xFFFF=0x479E; запись network byte order: 0x47, затем 0x9E.\n\nПроверка приёмником выполняется по header включая checksum и должна дать 0xFFFF в one's-complement arithmetic. 0x9E47 — byte-swapped representation, не корректное wire value.",
  "gap-pack3-10": "Outer tunnel endpoint 203.0.113.9 должен резолвиться в underlay независимо от overlay. При default via tunnel рекурсивный route lookup outer destination возвращается в тот же logical tunnel — recursive dependency.\n\nHost route 203.0.113.9/32 via physical next hop 192.0.2.1 dev E имеет более длинный prefix и обходит tunnel default. Маршрут via inner neighbor 10.10.0.2 только замыкает рекурсию.",
  "gap-pack3-11": "DNS referral at zone cut child.example.test содержит NS ns1.child.example.test; in-bailiwick glue A=192.0.2.53 в Additional даёт bootstrap reachability к delegated authoritative server (RFC 1034/1035).\n\nRecursive resolver отправляет исходный QNAME=app.child.example.test,QTYPE=A на 192.0.2.53. Glue A относится к NS host, не к app; пустая Answer referral не эквивалентна NXDOMAIN/NODATA.",
  "gap-pack3-12": "CNAME RR alias chain app.example.test→edge.example.test→app.example.test не имеет terminal A RRset. Resolver обнаруживает повтор QNAME и завершает alias chase с resolution failure; бесконечную рекурсию ограничивают.\n\nNXDOMAIN и NODATA имеют отдельную DNS response semantics; обнаружение circular CNAME не доказывает ни несуществование owner name, ни корректный отрицательный ответ. Возврат последнего alias не удовлетворяет QTYPE=A.",
  "gap-pack3-13": "DHCPv4 lease expiration occurs elapsed=3700>lease time=3600 при отсутствии подтверждённого renewal (RFC 2131). Client must cease using leased IPv4 address and return to INIT/initial acquisition.\n\nT1/RENEWING, T2/REBINDING — попытки получить ACK до expiry; сам retransmitted DHCPREQUEST не продлевает lease. Наличие link carrier или отсутствие DHCPNAK не сохраняет права использования expired address.",
  "gap-pack3-14": "HTTP PUT с If-Match:\"v7\" использует precondition evaluation against current strong entity tag \"v8\" (RFC 9110). Precondition false → 412 Precondition Failed; intended state-changing method не выполнен.\n\nКлиент должен GET current representation, merge concurrent edits и повторить conditional PUT with updated validator. Removing If-Match может привести к lost update; простая подмена validator без merge не защищает чужие изменения.",
  "gap-pack3-15": "HTTP HEAD response MUST NOT include message content независимо от Content-Length (RFC 9110). Content-Length:5000 может обозначать octet count response content для соответствующего GET, но actual response body length для HEAD равна zero.\n\nПри persistent HTTP/1.1 соединении parser завершает HEAD response после header section; чтение следующих 5000 octets как тела приведёт к desynchronization с subsequent message.",
  "gap-pack3-16": "SMTP per-recipient RCPT replies: 250 для A — accepted recipient; 450 для B — transient failure; 550 для C — permanent failure (RFC 5321). Последующий 250 после DATA подтверждает acceptance сообщения только для ранее принятых recipients.\n\nDelivery retry queue содержит B; A уже accepted responsibility, C требует permanent-failure handling/DSN, а не обычный deferred retry. DATA success не задним числом применяет 250 ко всем RCPT TO.",
  "gap-pack3-17": "RFC 6587 octet-counting frame имеет форму MSG-LEN SP SYSLOG-MSG; MSG-LEN — десятичное количество octets в encoded SYSLOG-MSG (RFC 5424), не число Unicode code points.\n\nTCP — byte stream: write boundaries отсутствуют у receiver API; newline внутри MSG не является reliable delimiter. Сначала UTF-8 encode, затем вычислить byte length, передать prefix и строго указанное число octets.",
  "gap-pack3-18": "NTP reply Originate Timestamp должен echo Transmit Timestamp client request (RFC 5905). Sent T1=123.250, received originate=122.500, следовательно association с текущим outstanding request не подтверждена.\n\nStratum=2 и LI=0 лишь прочие validity indicators; они не отменяют timestamp origin match. Подмена T1 для offset computation и использование чужого response рискуют replay/misassociation.",
  "gap-pack3-19": "OpenSSH ProxyJump (-J jump) устанавливает end-to-end SSH transport/session A↔B через jump, используя промежуточный TCP forwarding channel. User authentication к B выполняет SSH client A; private key/sign operation остаётся локально.\n\nAgent forwarding (-A) экспортирует agent socket capability на jump и нарушает explicit trust boundary даже без копии private key. Копирование encrypted key file на jump также не соответствует требованию local-only storage.",
  "gap-pack3-20": "TLS ALPN extension согласовала protocol identifier \"h2\" (RFC 7301), что требует HTTP/2 wire format (RFC 9113). Client connection preface включает 24-byte magic string и SETTINGS frame, затем request передаётся HEADERS frames с HTTP/2 pseudo-headers.\n\nHTTP/1.1 textual request line не совместима с h2; Upgrade: h2c относится к cleartext HTTP/2 transition, а не к уже negotiated h2 over TLS.",
  "gap-pack3-21": "В классическом Reno slow start (RFC 5681) на каждый ACK, подтверждающий новые данные в размере MSS, cwnd увеличивается на MSS: cwnd0=2 MSS → cwnd1=3 → cwnd2=4; ssthresh=16 не достигнут.\n\nЭкспоненциальный рост «примерно вдвое за RTT» следует из совокупности ACK за flight, а не из doubling на каждом ACK. Обработка двух полных ACK не эквивалентна двум round trips.",
  "gap-pack3-22": "RFC 6298 RTO backoff: initial timeout interval 1s, retransmission at t=1s; RTO←2×RTO=2s и таймер снова запускается после первого повтора.\n\nСледующий timeout/retransmission происходит at t=1+2=3s. Новое RTO — относительная длительность следующего ожидания, не absolute timestamp с начала передачи.",
  "gap-pack3-23": "При RTO RFC 5681 ограничивает новое ssthresh значением не выше max(FlightSize/2, 2×SMSS). В предложенном классическом варианте Reno при FlightSize=12 MSS выбирается 6 MSS; cwnd уменьшается до loss window в один MSS.\n\nssthresh — порог перехода от slow start, а cwnd — текущее ограничение объёма в полёте. Сохранение cwnd=6 MSS не соответствует реакции на тайм-аут; переходы fast retransmit/fast recovery нельзя переносить на потерю, обнаруженную по RTO.",
  "gap-pack3-24": "RFC 5961 RST validation для established TCP: если SEG.SEQ==RCV.NXT, RST принимается; если RST sequence merely within receive window, receiver sends challenge ACK и сохраняет соединение; вне окна — silent discard.\n\nRCV.NXT=10000, RCV.WND=4000 → [10000,13999]; 11000 попадает внутрь, но не равно 10000. Поэтому challenge ACK, а не immediate abort/FIN handling.",
  "gap-pack3-25": "PAWS по RFC 7323 сравнивает TSval сегмента с TS.Recent для соответствующего направления. 19000 < 20000 при отсутствии wraparound и idle exceptions — stale timestamp, сегмент исключается даже при SEG.SEQ=RCV.NXT.\n\nTCP timestamps используют монотонное пространство relative timestamps peer, не wall-clock synchronization. Откат TS.Recent нарушил бы защиту against wrapped sequence space/old duplicate segments.",
  "gap-pack3-26": "Linux connected UDP socket задаёт remote peer tuple 198.51.100.20:5353 через connect(2) без TCP-style handshake. Receive demultiplexing привязывает сокет к локальной паре и выбранной remote IP:port.\n\nDatagram A полностью совпадает; B source port=5354, C source IP=198.51.100.21, поэтому не выдаются данному socket. TCP reliability/ordering connect для UDP не добавляет.",
  "gap-pack3-27": "UDP не содержит transport-level deduplication of application transactions. Для неидемпотентного increment операция должна иметь уникальный request/operation ID, идентичный на повторе, а сервер — хранить per-client ID→result.\n\nПроверка ID и изменение counter должны быть atomic относительно concurrent retransmissions; duplicate request возвращает cached result. IP:port характеризует peer, а не уникальность логической операции.",
  "gap-pack3-28": "По состоянию TCP-отправителя SND.UNA=2000 и SND.NXT=3000; допустимое подтверждение не может относиться к байтам за SND.NXT. ACK=3500 подтверждает неотправленное пространство последовательности и отклоняется без продвижения SND.UNA; отправляется текущее ACK по правилам обработки установленного соединения (RFC 9293).\n\nОбрезание ACK до 3000 создало бы неподтверждённый получателем результат. Продвижение SND.NXT по чужому ACK также недопустимо. Проверка входящего SEG.SEQ относится к состоянию приёма и не заменяет проверку ACK относительно собственного состояния отправки.",
  "gap-pack3-29": "TCP MSS option advertises receive capability of sender of SYN (RFC 9293). A MSS=1460 ограничивает B→A, B MSS=1200 ограничивает A→B. PMTU=1500, IPv4/TCP headers=20+20 дают path payload ceiling=1460.\n\nDirectional maxima: A→B min(1200,1460)=1200; B→A min(1460,1460)=1460. MSS не negotiated common scalar и не совпадает с rwnd/cwnd.",
  "gap-pack3-30": "TCP_NODELAY отключает алгоритм Нейгла на отправляющем сокете Linux (tcp(7)). При неподтверждённом коротком сегменте Nagle может удерживать следующую отправку размером меньше MSS до ACK или накопления полного сегмента; rwnd и cwnd в условии передачу допускают.\n\nTCP_CORK задерживает неполные TCP-сегменты ради накопления. TCP_QUICKACK управляет локальной политикой подтверждений входящих данных, SO_KEEPALIVE — проверкой простаивающего соединения. TCP_NODELAY не отменяет flow/congestion control и не создаёт границы прикладных сообщений."
};

for (const [id, explanation] of Object.entries(APPLIED_INDIVIDUAL_DEEP)) {
  if (!/^gap-pack[123]-(?:0[1-9]|[12]\d|30)$/.test(id)) continue;
  explanation.plain = explanation.deep;
  const technical = explanation.professional?.deep ?? GAP_PACK_PRO_TEXT[id];
  if (!technical) continue;
  explanation.pro = technical;
}
